def countBandPaths(n, w):
    MOD = 10 ** 9 + 7
    ways = [0] * n
    for r in range(n):
        lo = max(0, r - w)
        hi = min(n - 1, r + w)
        if lo > 0:
            ways[lo - 1] = 0
        for c in range(lo, hi + 1):
            if r == 0 and c == 0:
                ways[c] = 1
            else:
                v = ways[c]
                if c > 0:
                    v += ways[c - 1]
                ways[c] = v % MOD
    return ways[n - 1]
